#include <stdlib.h>
#include <string.h>
#ifdef _OPENMP
#include <omp.h>
#endif

#if defined(__AVX512F__)
#define VL 16
#define MR 8
#else
#define VL 8
#define MR 6
#endif
#define NR (2 * VL)
#define MC (MR * 16)
#define KC 256

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
    }
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

/* Pack mc rows of A (cols p0..p0+kc) into MR-interleaved panels, reading rows contiguously. */
static void pack_a_block(const float *A, int n, int i0, int mc, int p0, int kc, float *ap)
{
    for (int p = 0; p < mc; p += MR) {
        int mr = mc - p < MR ? mc - p : MR;
        int i;
        for (i = 0; i < mr; i++) {
            const float *src = A + (size_t)(i0 + p + i) * n + p0;
            for (int k = 0; k < kc; k++)
                ap[k * MR + i] = src[k];
        }
        for (; i < MR; i++)
            for (int k = 0; k < kc; k++)
                ap[k * MR + i] = 0.0f;
        ap += (size_t)kc * MR;
    }
}

static void pack_b_panel(const float *B, int n, int p0, int kc, int j0, int nr, float *bp)
{
    if (nr == NR) {
        for (int k = 0; k < kc; k++)
            memcpy(bp + (size_t)k * NR, B + (size_t)(p0 + k) * n + j0, NR * sizeof(float));
        return;
    }
    for (int k = 0; k < kc; k++) {
        const float *src = B + (size_t)(p0 + k) * n + j0;
        float *dst = bp + (size_t)k * NR;
        int j;
        for (j = 0; j < nr; j++) dst[j] = src[j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

static float *g_bp = NULL;
static size_t g_bsz = 0;

void matmul(const float *A, const float *B, float *C, int n)
{
    int npanB = (n + NR - 1) / NR;
    size_t bstride = ((size_t)npanB * NR * KC + 1023) / 1024 * 1024;
    size_t need = 2 * bstride * sizeof(float);
    if (need > g_bsz) {
        free(g_bp);
        need = (need + 4095) / 4096 * 4096;
        g_bp = (float *)aligned_alloc(4096, need);
        g_bsz = need;
    }
    float *bpall = g_bp;

    int nib = (n + MC - 1) / MC;
    long U = (long)nib * npanB;

#pragma omp parallel
    {
        int tid = 0, nth = 1;
#ifdef _OPENMP
        tid = omp_get_thread_num();
        nth = omp_get_num_threads();
#endif
        float ap[MC * KC] __attribute__((aligned(64)));
        float tile[MR * NR] __attribute__((aligned(64)));
        long u0 = U * tid / nth, u1 = U * (tid + 1) / nth;

        int pidx = 0;
        for (int pc = 0; pc < n; pc += KC, pidx++) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);
            float *bp = bpall + (size_t)(pidx & 1) * bstride;

            /* Cooperative B pack; the implicit barrier is the only sync per pc.
               Double buffering makes it safe to pack the next pc while others compute. */
#pragma omp for schedule(static)
            for (int q = 0; q < npanB; q++) {
                int j0 = q * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                pack_b_panel(B, n, pc, kc, j0, nr, bp + (size_t)q * kc * NR);
            }

            int cur_ib = -1, i0 = 0, mc = 0;
            for (long u = u0; u < u1; u++) {
                int ib = (int)(u / npanB), q = (int)(u % npanB);
                if (ib != cur_ib) {
                    cur_ib = ib;
                    i0 = ib * MC;
                    mc = n - i0 < MC ? n - i0 : MC;
                    pack_a_block(A, n, i0, mc, pc, kc, ap);
                }
                int j = q * NR;
                int nr = n - j < NR ? n - j : NR;
                const float *bpan = bp + (size_t)q * kc * NR;
                for (int i = 0; i < mc; i += MR) {
                    int mr = mc - i < MR ? mc - i : MR;
                    const float *apan = ap + (size_t)(i / MR) * kc * MR;
                    float *cp = C + (size_t)(i0 + i) * n + j;
                    if (mr == MR && nr == NR) {
                        kernel(kc, apan, bpan, cp, n, first);
                    } else {
                        kernel(kc, apan, bpan, tile, NR, 1);
                        for (int ii = 0; ii < mr; ii++) {
                            float *crow = cp + (size_t)ii * n;
                            const float *trow = tile + ii * NR;
                            if (first)
                                for (int jj = 0; jj < nr; jj++) crow[jj] = trow[jj];
                            else
                                for (int jj = 0; jj < nr; jj++) crow[jj] += trow[jj];
                        }
                    }
                }
            }
        }
    }
}
